{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "CP-331,684, the closest retrieved analogue (Morgan 0.3425), had a human oral bioavailability of 27% from IV-oral comparison, above the 20% threshold; its aminopyridine/aminoethanol polar scaffold is the most transferable to the query's aminothiazole/aminoethanol scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Labetalol, a structurally related aryl ethanolamine with an amide and first-pass metabolism, showed absolute oral bioavailability of 28% (19-49%) after 100 mg oral vs IV, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Bevantolol, another beta-blocker-like amino alcohol, had a mean absolute oral bioavailability of 57% (range 26-98%) after 50 mg oral vs IV, supporting high bioavailability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Epanolol had low absolute oral bioavailability (7.06±3.15%) after oral solution in fasted volunteers, but its phenol/nitrile aryloxypropanolamine structure is less transferable to the query's aminothiazole acetanilide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Salmeterol has very low oral bioavailability (~1%), but its long lipophilic saligenin ether structure differs substantially from the query and is a weaker transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C60"],
      "claim": "Propafenone showed low absolute bioavailability (4.8%) for 150 mg tablets, but propafenone's F is highly variable (5-143%) due to CYP2D6 polymorphism and its ketone/propylamine structure is not closely analogous.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable human data (CP-331,684 27%; labetalol ~28%; bevantolol 57%) support F ≥20%. Low-F analogues are less structurally aligned or highly variable and do not outweigh the high-side evidence; prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact query molecule.",
    "Closest analogue CP-331,684 still differs in heteroaromatic and amide/ether arrangement.",
    "First-pass metabolic liability of the aminothiazole acetanilide moiety is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

